// Определяем тип файла по СОДЕРЖИМОМУ (сигнатуре), затем по имени и MIME.
// Так работают и multipart-загрузка, и base64 из JSON, и файлы, пришедшие как «bin».
const item = $input.item;
const binary = item.binary || {};
const key = Object.keys(binary)[0];

if (!key) {
  return { json: { fileType: 'unknown', ext: '', error: item.json.error || 'Нет файла: загрузите его через форму или отправьте на вебхук' } };
}

const b = binary[key];
const KNOWN = ['pdf', 'png', 'jpg', 'jpeg', 'tif', 'tiff', 'bmp', 'doc', 'docx', 'xls', 'xlsx', 'xlsm'];
const MIME = {
  pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', tif: 'image/tiff', tiff: 'image/tiff', bmp: 'image/bmp',
  doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xlsm: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
};

// --- 1. сигнатура файла ---
const sniff = (buf) => {
  if (!buf || buf.length < 8) return '';
  if (buf.slice(0, 4).toString('latin1') === '%PDF') return 'pdf';
  if (buf[0] === 0x89 && buf.slice(1, 4).toString('latin1') === 'PNG') return 'png';
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'jpg';
  const h4 = buf.slice(0, 4).toString('hex');
  if (h4 === '49492a00' || h4 === '4d4d002a') return 'tif';
  if (buf[0] === 0x42 && buf[1] === 0x4d) return 'bmp';
  if (h4 === '504b0304') {                                   // zip: docx / xlsx
    if (buf.indexOf('word/document.xml') >= 0) return 'docx';
    if (buf.indexOf('xl/workbook.xml') >= 0 || buf.indexOf('xl/worksheets/') >= 0) return 'xlsx';
    return 'zip';
  }
  if (buf.slice(0, 8).toString('hex') === 'd0cf11e0a1b11ae1') {   // OLE2: doc / xls
    if (buf.indexOf(Buffer.from('WordDocument', 'utf16le')) >= 0) return 'doc';
    if (buf.indexOf(Buffer.from('Workbook', 'utf16le')) >= 0 || buf.indexOf(Buffer.from('Book', 'utf16le')) >= 0) return 'xls';
    return 'ole';
  }
  return '';
};

let buf = null;
try { buf = await this.helpers.getBinaryDataBuffer($itemIndex, key); } catch (e) { buf = null; }
let ext = sniff(buf);

// --- 2. имя файла, потом fileExtension, потом MIME ---
const name = String(b.fileName || '');
if (!ext || ext === 'zip' || ext === 'ole') {
  const dot = name.lastIndexOf('.');
  const fromName = dot >= 0 ? name.slice(dot + 1).toLowerCase() : '';
  const fromExt = String(b.fileExtension || '').toLowerCase();
  const fromMime = Object.keys(MIME).find(k => MIME[k] === String(b.mimeType || '').toLowerCase()) || '';
  const guess = [fromName, fromExt, fromMime].find(x => KNOWN.includes(x)) || '';
  ext = guess || '';
}
if (ext === 'xlsm') ext = 'xlsx';

// Тип файла для развилки
let fileType = 'unknown';
if (ext === 'pdf') fileType = 'pdf';
else if (['png', 'jpg', 'jpeg', 'tif', 'tiff', 'bmp'].includes(ext)) fileType = 'image';
else if (ext === 'docx') fileType = 'docx';
else if (ext === 'doc') fileType = 'doc';
else if (ext === 'xlsx') fileType = 'xlsx';
else if (ext === 'xls') fileType = 'xls';

// Исправляем метаданные файла (после «bin» дальше по цепочке всё должно быть корректно)
const dot2 = name.lastIndexOf('.');
const base = (dot2 > 0 && name.length - dot2 <= 6) ? name.slice(0, dot2) : (name || 'document');
const fixed = fileType === 'unknown' ? b : { ...b, fileName: base + '.' + ext, fileExtension: ext, mimeType: MIME[ext] };

return {
  json: {
    ext: ext || String(b.fileExtension || ''),
    fileType,
  },
  // Приводим бинарное поле к имени "file" (форма и вебхук называют его по-разному)
  binary: { file: fixed },
};

// Строки листа -> текст. Ячейки строки через « | », пустые пропускаем
const items = $input.all();
const first = items[0] ? items[0].json : {};
if (items.length === 1 && first.error && Object.keys(first).length === 1) {
  return [{ json: { text: '', source: 'excel', error: String(first.error.message || first.error) } }];
}
const lines = [];
for (const it of items) {
  const cells = Object.values(it.json)
    .map(v => String(v ?? '').replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  if (cells.length) lines.push(cells.join(' | '));
}
const text = lines.join('\n');
return [{ json: { text, source: 'excel', error: text ? null : 'Excel пуст (проверьте, что данные на первом листе)' } }];

// .docx — это zip. Помечаем файл как zip, чтобы его распаковал узел Compression
const b = $input.item.binary.file;
return {
  json: $input.item.json,
  binary: { file: { ...b, fileName: 'document.zip', fileExtension: 'zip', mimeType: 'application/zip' } },
};

// word/document.xml -> текст. Таблицы: ячейки через « | », строки через перевод строки
const item = $input.first();
const bin = item.binary || {};
if (item.json && item.json.error && !Object.keys(bin).length) throw new Error(String(item.json.error.message || item.json.error));
const key = Object.keys(bin).find(k => bin[k].fileName === 'word/document.xml')
  || Object.keys(bin).find(k => /document\.xml$/.test(bin[k].fileName || ''));
if (!key) throw new Error('В DOCX не найден word/document.xml');

const xml = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf8');

const tok = /<w:tc(?:\s[^>]*)?>|<\/w:tc>|<\/w:tr>|<\/w:p>|<w:tab\/>|<w:br[^>]*\/>|<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g;
let out = '';
let cell = 0;
let m;
while ((m = tok.exec(xml)) !== null) {
  const t = m[0];
  if (m[1] !== undefined) out += m[1];
  else if (t.startsWith('<w:tc')) cell++;
  else if (t === '</w:tc>') { cell = Math.max(0, cell - 1); out += ' | '; }
  else if (t === '</w:tr>') out += '\n';
  else if (t === '</w:p>') out += cell > 0 ? ' ' : '\n';
  else if (t === '<w:tab/>') out += ' ';
  else out += cell > 0 ? ' ' : '\n';
}

const dec = (s) => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');

const text = dec(out)
  .replace(/[ \t\u00a0]+/g, ' ')
  .replace(/( \| )+\n/g, '\n')
  .replace(/ \| $/gm, '')
  .replace(/ +\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (text.length < 10) throw new Error('DOCX пуст или содержит только картинки');
return [{ json: { text, source: 'docx' } }];

// .doc (Word 97-2003, OLE2) -> текст без внешних сервисов и библиотек
const item = $input.first();
const key = Object.keys(item.binary || {})[0];
if (!key) throw new Error('Нет бинарного файла');
const buf = await this.helpers.getBinaryDataBuffer(0, key);

if (buf.length > 1 && buf[0] === 0x50 && buf[1] === 0x4b) {
  throw new Error('Файл с расширением .doc на самом деле DOCX (zip). Переименуйте его в .docx');
}
if (buf.slice(0, 5).toString('latin1') === '{\\rtf') {
  throw new Error('Файл с расширением .doc на самом деле RTF. Пересохраните его как DOCX');
}
if (buf.readUInt32BE(0) !== 0xd0cf11e0 || buf.readUInt32BE(4) !== 0xa1b11ae1) {
  throw new Error('Это не Word 97-2003 (.doc): нет сигнатуры OLE2');
}

// ---------- OLE2 (compound file) ----------
const secSize = 1 << buf.readUInt16LE(0x1e);
const miniSize = 1 << buf.readUInt16LE(0x20);
const cutoff = buf.readUInt32LE(0x38);
const sec = (n) => buf.slice((n + 1) * secSize, (n + 2) * secSize);
const END = 0xfffffffe;

const fatSecs = [];
for (let i = 0; i < 109; i++) { const s = buf.readUInt32LE(0x4c + i * 4); if (s < 0xfffffffa) fatSecs.push(s); }
let dif = buf.readUInt32LE(0x44);
for (let c = buf.readUInt32LE(0x48); c > 0 && dif < 0xfffffffa; c--) {
  const b = sec(dif);
  for (let i = 0; i < secSize / 4 - 1; i++) { const s = b.readUInt32LE(i * 4); if (s < 0xfffffffa) fatSecs.push(s); }
  dif = b.readUInt32LE(secSize - 4);
}
const fat = [];
for (const s of fatSecs) { const b = sec(s); for (let i = 0; i < secSize / 4; i++) fat.push(b.readUInt32LE(i * 4)); }

const chain = (start, table) => { const r = []; let s = start, g = 0; while (s < 0xfffffffa && g++ < 1e6) { r.push(s); s = table[s]; } return r; };
const readBig = (start) => Buffer.concat(chain(start, fat).map(sec));

// каталог
const dir = readBig(buf.readUInt32LE(0x30));
const entries = [];
for (let o = 0; o + 128 <= dir.length; o += 128) {
  const len = dir.readUInt16LE(o + 0x40);
  if (!len) continue;
  entries.push({
    name: dir.slice(o, o + len - 2).toString('utf16le'),
    type: dir[o + 0x42],
    start: dir.readUInt32LE(o + 0x74),
    size: dir.readUInt32LE(o + 0x78),
  });
}
const root = entries.find(e => e.type === 5);
let mini = null, miniFat = null;
const readStream = (name) => {
  const e = entries.find(x => x.type === 2 && x.name === name);
  if (!e) return null;
  if (e.size < cutoff) {
    if (!mini) {
      mini = readBig(root.start);
      const mf = readBig(buf.readUInt32LE(0x3c));
      miniFat = []; for (let i = 0; i + 4 <= mf.length; i += 4) miniFat.push(mf.readUInt32LE(i));
    }
    return Buffer.concat(chain(e.start, miniFat).map(s => mini.slice(s * miniSize, (s + 1) * miniSize))).slice(0, e.size);
  }
  return readBig(e.start).slice(0, e.size);
};

// ---------- Word: FIB и таблица кусков текста ----------
const wd = readStream('WordDocument');
if (!wd) throw new Error('В файле нет потока WordDocument');
if (wd.readUInt16LE(0) !== 0xa5ec) throw new Error('Неизвестная версия Word');
const flags = wd.readUInt16LE(0x0a);
if (flags & 0x0100) throw new Error('Документ зашифрован (защищён паролем)');
const tbl = readStream((flags & 0x0200) ? '1Table' : '0Table');
if (!tbl) throw new Error('Не найден поток таблиц (0Table/1Table)');

let o = 34 + wd.readUInt16LE(32) * 2;       // после fibRgW
const cslw = wd.readUInt16LE(o); const lwStart = o + 2; o = lwStart + cslw * 4;
const ccpText = wd.readUInt32LE(lwStart + 3 * 4);   // длина основного текста
const pairs = o + 2;
const fcClx = wd.readUInt32LE(pairs + 33 * 8);
const lcbClx = wd.readUInt32LE(pairs + 33 * 8 + 4);

let p = fcClx; const endClx = fcClx + lcbClx;
while (p < endClx && tbl[p] === 1) p += 3 + tbl.readUInt16LE(p + 1);   // пропускаем Prc
if (tbl[p] !== 2) throw new Error('Не найден Pcdt (piece table)');
const plcLen = tbl.readUInt32LE(p + 1); p += 5;
const nPieces = Math.floor((plcLen - 4) / 12);

const cp1252 = { 0x80: '€', 0x82: '‚', 0x83: 'ƒ', 0x84: '„', 0x85: '…', 0x86: '†', 0x87: '‡', 0x88: 'ˆ', 0x89: '‰', 0x8a: 'Š', 0x8b: '‹', 0x8c: 'Œ', 0x8e: 'Ž', 0x91: '‘', 0x92: '’', 0x93: '“', 0x94: '”', 0x95: '•', 0x96: '–', 0x97: '—', 0x98: '˜', 0x99: '™', 0x9a: 'š', 0x9b: '›', 0x9c: 'œ', 0x9e: 'ž', 0x9f: 'Ÿ' };
let raw = '';
for (let i = 0; i < nPieces; i++) {
  const cp0 = tbl.readUInt32LE(p + i * 4), cp1 = tbl.readUInt32LE(p + (i + 1) * 4);
  if (cp0 >= ccpText) break;
  const n = Math.min(cp1, ccpText) - cp0;
  const fcRaw = tbl.readUInt32LE(p + (nPieces + 1) * 4 + i * 8 + 2);
  if (fcRaw & 0x40000000) {
    const off = (fcRaw & 0x3fffffff) >>> 1;
    for (let k = 0; k < n; k++) { const b = wd[off + k]; raw += (cp1252[b] || String.fromCharCode(b)); }
  } else {
    raw += wd.slice(fcRaw, fcRaw + n * 2).toString('utf16le');
  }
}

// ---------- очистка спецсимволов и полей ----------
let s = '', depth = [];
for (const ch of raw) {
  const c = ch.charCodeAt(0);
  if (c === 0x13) { depth.push('i'); continue; }                 // начало поля
  if (c === 0x14) { if (depth.length) depth[depth.length - 1] = 'r'; continue; }   // результат поля
  if (c === 0x15) { depth.pop(); continue; }
  if (depth.includes('i')) continue;                             // код поля (инструкция) пропускаем
  if (c === 0x0d || c === 0x0b || c === 0x0c) s += '\n';
  else if (c === 0x07) s += '\x07';
  else if (c === 0x09 || c === 0xa0) s += ' ';
  else if (c === 0x1e) s += '-';
  else if (c < 0x20) continue;
  else s += ch;
}

// ---------- таблицы: ячейки « | », строки — с новой строки ----------
const tokens = s.split('\x07');
const last = tokens.pop();                       // текст после последней ячейки
const lines = [];
let row = [], N = null;
const flush = () => {
  const cells = row.map(c => c.replace(/\s+/g, ' ').trim()).filter(Boolean);
  if (cells.length) lines.push(cells.join(' | '));
  if (N === null) N = row.length;
  row = [];
};
for (let t of tokens) {
  if (row.length === 0 && t.includes('\n')) {    // до первой ячейки — обычные абзацы
    const k = t.lastIndexOf('\n');
    lines.push(...t.slice(0, k).split('\n'));
    t = t.slice(k + 1);
    N = null;                                    // новая таблица
  }
  if (row.length > 0 && N !== null && row.length >= N) {
    if (t === '') { flush(); continue; }         // маркер конца строки
    flush();                                     // строка была короче/длиннее — начинаем новую
  } else if (row.length > 0 && N === null && t === '' && row.some(c => c.trim())) {
    flush(); continue;                           // первая строка таблицы закончилась
  }
  row.push(t);
}
if (row.length) flush();
lines.push(...last.split('\n'));

const text = lines.map(l => l.replace(/[ \t]+/g, ' ').trim()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
if (text.length < 10) throw new Error('DOC пуст или не удалось извлечь текст');
return [{ json: { text, source: 'doc' } }];

// Достаём файл из запроса вебхука. Поддерживаются три способа:
//  1) multipart/form-data (поле с файлом любое, например file);
//  2) «сырое» тело запроса (application/pdf, application/octet-stream и т.п.);
//  3) JSON с файлом в base64: {"ФайлBase64": "...", "ИмяФайла": "акт.pdf"}.
// Имя файла (если не пришло вместе с файлом): заголовок X-Filename, параметр ?name=, поле ИмяФайла.
const item = $input.item;
const j = item.json || {};
const body = (j.body && typeof j.body === 'object') ? j.body : {};
const query = j.query || {};
const headers = j.headers || {};

const pick = (o, names) => {
  for (const n of names) {
    if (o[n] !== undefined && o[n] !== null && o[n] !== '') return o[n];
  }
  return undefined;
};
const dec = (s) => { try { return decodeURIComponent(String(s)); } catch (e) { return String(s); } };
const nameFromRequest = () => {
  const n = pick(body, ['ИмяФайла', 'имяФайла', 'fileName', 'filename', 'name'])
    || headers['x-filename'] || headers['x-file-name'] || query.name || query.filename || query['имя'];
  return n ? dec(n) : '';
};

// 1-2) файл уже пришёл как бинарные данные
const keys = Object.keys(item.binary || {});
if (keys.length) {
  const b = item.binary[keys[0]];
  const hasExt = /\.[A-Za-z0-9]{2,5}$/.test(String(b.fileName || ''));
  const named = nameFromRequest();
  const fileName = hasExt ? b.fileName : (named || b.fileName || 'document');
  return { json: j, binary: { file: { ...b, fileName } } };
}

// 3) base64 в JSON
let b64 = pick(body, ['ФайлBase64', 'файлBase64', 'fileBase64', 'file_base64', 'base64', 'file', 'data', 'content']);
if (typeof b64 === 'string') {
  let mime = '';
  const m = /^data:([^;,]*)(?:;[^,]*)?;base64,/i.exec(b64);
  if (m) { mime = m[1]; b64 = b64.slice(m[0].length); }
  b64 = b64.replace(/\s+/g, '');
  const buf = Buffer.from(b64, 'base64');
  if (!buf.length) throw new Error('Файл в base64 пустой или повреждён');
  const bin = await this.helpers.prepareBinaryData(buf, nameFromRequest() || 'document', mime || undefined);
  return { json: j, binary: { file: bin } };
}

throw new Error('В запросе нет файла: пришлите multipart-поле с файлом, сырое тело или JSON {"ФайлBase64": "...", "ИмяФайла": "..."}');

// ЕДИНЫЙ ВЫВОД: один и тот же набор полей для любого типа файла и для ошибок
const j = $json || {};
let cfg = {}, file = {};
try { const c = $('Config').first(); cfg = c.json || {}; file = (c.binary || {}).file || {}; } catch (e) {}

const fileType = cfg.fileType || j.fileType || 'unknown';
const ext = cfg.ext || j.ext || null;
const bySource = { pdf: 'pdf-text-layer', docx: 'docx', doc: 'doc', xlsx: 'excel', xls: 'excel' };
let text = String(j.text || '').trim();
let error = j.error ? String(j.error.message || j.error) : null;
let source = j.source || bySource[fileType] || 'none';

if (fileType === 'image') {
  text = '';
  error = 'Изображения не поддерживаются: распознавание (OCR) отключено';
} else if (fileType === 'pdf' && !j.source) {
  // ветка «нет текстового слоя»: короткий мусор из PDF не считаем результатом
  text = '';
  source = 'none';
  error = error || 'PDF без текстового слоя (скан): распознавание (OCR) отключено';
} else if (fileType === 'unknown' && !error) {
  error = 'Неподдерживаемый формат файла: ' + (ext || '?') + '. Допустимо: pdf, doc, docx, xls, xlsx';
}
if (!text && !error) error = 'Текст не извлечён';

return {
  json: {
    ok: !!text && !error,
    text,
    source,                       // pdf-text-layer | docx | doc | excel | none
    fileType,                     // pdf | image | docx | doc | xlsx | xls | unknown
    fileName: file.fileName || null,
    ext,
    chars: text.length,
    pages: j.pages ?? null,
    error,
  },
};
